"""Type-based semantic review requirements, independent of cases and SQL literals."""

QUALITY_CRITERIA = {
    "type_fit": "The content belongs to its declared node type; calculation syntax alone does not justify a Metric.",
    "minimality": "NL semantic minimality: no decomposition into two or more complete Concept/Metric/NL-term meanings with distinct independently identifiable field/value/operation matching roles that reconstruct the whole meaning. On failure give units, matches, composition and evidence; units need not already exist as nodes. Joint physical implementation, target overlap or definition expansion alone does not prove a split. Identifier/name representations of one object are not different NL meanings by themselves. Prefer the Question's business term, not a name derived only from the selected SQL column. Unfolding a supported category definition into parent plus attribute restriction alone does not prove NL composition. Do not require extra subclass knowledge or prefer attributes categorically; use Question/SQL and available database evidence. Overlap, mutability and absence of extra Rules do not decide this. If evidence is inconclusive, report that rather than inventing a split.",
    "grounding": "Concept matches Columns/Values, not Tables. Outer items may realize one object through identifier/name roles; inner fields must be jointly necessary. A governed Value already identifies its owner Column; repeating that Column only to restate value equality is not a joint match. Roles are explained in descriptions, not automatically separate Concepts or interchangeable operands. A source Table is metadata, not a Concept target. Check actual endpoint meanings and supported identity scope; table grain/coverage belongs in metadata.",
    "metric_minimality": "Apply the same NL semantic split test as Concept: identify complete Concept/Metric/NL-term units, their separate field/value/operation matches and a composition preserving the candidate meaning and restrictions. Reject supported decompositions, not merely long names or multi-operator formulas. A candidate-authored business definition, formula or unit is no exemption. A request operator applied to an independently matched term remains decomposable even when nested or restated as a business quantity. Distinguish it from operands implementing one supported NL term; unfolding that term's definition is not itself NL composition. Preserve intrinsic population, unit, grain, constants and coupled operations. Units need not exist as nodes; target overlap is allowed. Real calculation is a separate requirement. Do not force helper Metrics or create Rules for ordinary operations. Report inconclusive when the semantic boundary lacks evidence.",
    "formula_scope": "A complete defining business formula, not generic request aggregation or its filters/grouping. Interpret each placeholder by its bound Concept/Metric/physical meaning, not its variable name: an object or label does not become a precomputed count because the key contains count. Required arithmetic/aggregations must occur in expression, not only in a plan; compare formula, bindings, pattern and SQL implementation.",
    "decision_value": "An evidenced choice between semantically consequential implementations beyond Concept matches or Metric formulas. Routine request matching or literal/calendar filtering is not an extra decision unless case evidence establishes a consequential ambiguity or policy beyond the binding. Ordinary operators, equivalent SQL spellings and hypothetical alternatives are insufficient; listing irrelevant fields does not establish a choice. Shared registry intents must fit; extensions explain meaning, registry gap and the supported decision. A Rule must not repeat a static Concept mapping. Content selection may choose multiple matching groups; presentation holds the selected business content fixed. Only claims of observed corrections require actual errors.",
    "atomicity": "Action minimality: one minimal, complete, reusable generation behavior. On failure identify independently applicable complete behaviors and their conditions. Required implementation steps of one behavior are not separate actions merely because they use different SQL operators. Preserve necessary scope and executable detail; brevity and tag count do not establish atomicity. Vary content selection, presentation and row filtering independently to test for bundled decisions; do not hide a binding choice in a ranking/formatting action. Decision value is assessed separately.",
    "abstraction": "Parameterize incidental runtime values and K; linked business names may clarify scope in condition/action. Rebinding business objects requires checking applicability, not banning their names. Preserve intrinsic business constants.",
    "condition_action": "Action is concrete enough to implement; any local SQL pattern and placeholders agree with condition, linked operands and evidence. Preserve operand, direction, grain, cardinality and NULL semantics; no invented fallback K or NULL policy.",
    "structure": "Evidence jointly supports an occurrence, participants and related occurrence time or place.",
    "endpoint_meaning": "Both endpoints retain their declared meaning; a value/attribute is not its owning object or a selected object population. An extends relation must entail its parent meaning for every fact with the same endpoint roles; shared JSON node types alone do not establish semantic specialization. has_attribute targets an attribute-role Concept; is_a requires comparable class meanings, not an object-to-attribute link.",
    "predicate_precision": "For semantic endpoints, require a supported role-specific business predicate. has_attribute is an abstract base, never an actual edge predicate. Reuse or declare a concrete relation contract; optional extends=has_attribute denotes specialization. If no concrete role is supported, investigate or omit the unsupported edge, not fall back to has_attribute. If the target supplies a supported named role, the predicate should name that role; saying it is an attribute in description does not suffice. Its description must begin with a positive business statement, not merely that the source record stores the target field. Read source + predicate + target as a business statement with the actual endpoint meanings; keep recording/provenance limits in description. Physical grounding/catalog predicates retain their physical meaning. Do not use related_to merely to carry notes that two attributes differ or do not imply each other; put such limits in their supported owner/attribute descriptions.",
    "scope": "Semantic descriptions explain the business role first; physical grounding/catalog descriptions explain mapping. Add only material evidenced constraints, not mandatory boilerplate for every nullable field: cardinality, optionality, applicability or inference limits, with record/object/time scope. Keys constrain records, not lifetime business identity. Missing dates do not imply missing events unless evidenced. Reject invented constraints, metadata dumps, profile counts, probe SQL or repeated endpoint definitions; usually one or two sentences suffice, not a hard length cap.",
    "support": "Case, metadata and recorded evidence support the claim; SQL equality alone is insufficient. Scoped input omission is not evidence of database-wide absence. Identity, grain and missing-field claims need evidence covering their asserted scope.",
    "graph_consistency": "Compare this unit with supplied current nodes, matching groups, formulas and edges. Definitions, operand roles, grain, scope and correlated event roles must agree. Equivalent definitions in the same scope should reuse a canonical identity only with evidence of equivalence. Cite the other IDs and exact conflict or repeated definition; a cycle across unrelated predicates or overlapping targets alone is not a defect. Compare overlapping Rule conditions and shared decisions, including decisions embedded in compound actions: separate Gold support does not establish mutual compatibility. Distinguish supported conditional behavior, complementary knowledge and competing alternatives. Do not require graph minimality or missing business knowledge.",
    "assertion_nonredundancy": "Reject redundancy only with a same-scope equivalent counterpart or a supplied contract and independent supporting path, and evidence that consolidation preserves current consumers, scope and restrictions. Cite edge IDs and the rule. Logical derivability alone is not a defect: retain a materialized assertion if consumers require it or cannot recover the inference; do not fail this check solely for that candidate. Direct formula operands and catalog ownership cannot be replaced by indirect paths. Never use conflicts as proof, assume undeclared transitivity, or require structure compression; unproved or unsafe redundancy does not authorize deletion.",
    "removal_safety": "Deletion preserves supported behavior and does not leave dependent knowledge invalid.",
}


def required_quality_checks(candidate, *, relation=None):
    if candidate is None:
        return ["removal_safety"]
    if relation is not None:
        return ["endpoint_meaning", "predicate_precision", "scope", "support", "graph_consistency", "assertion_nonredundancy"]
    kind = candidate.get("node_type")
    checks = {
        "concept": ["type_fit", "minimality", "grounding", "support"],
        "metric": ["type_fit", "metric_minimality", "formula_scope", "support"],
        "event": ["type_fit", "structure", "support"],
        "generation_rule": ["type_fit", "decision_value", "atomicity", "abstraction", "condition_action", "support"],
    }.get(kind, ["type_fit", "support"])
    return [*checks, "graph_consistency"]
